    /**
     * Method to retrieve the Customer via an FindCustomerQuery
     * @return 	query	FindCustomerQuery
     */
    @SuppressWarnings("unused")
    public Customer find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Customer - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Customers
     *
     * @param	query	FindAllCustomerQuery 
     * @return 	List<Customer> 
     */
    @SuppressWarnings("unused")
    public List<Customer> findAll( FindAllCustomerQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Customer - {0}", exc.getMessage() );
    	}
    	return null;
    }


